class LabAssayService:
    @staticmethod
    def get_assay(code: str) -> Optional[LabAssay]:
        return LAB_ASSAYS_DATABASE.get(code.strip())

    @staticmethod
    def search(query: str) -> List[LabAssay]:
        q = query.lower().strip()
        return [a for a in LAB_ASSAYS_DATABASE.values() if q in a.assay_name.lower() or q in a.assay_code.lower()][:50]
